insert into public.projects(title,slug,summary,category,technologies,repository_url,demo_url,problem,solution,architecture,challenges,outcomes,status,featured,sort_order) values
('Spotter — Weather-Aware Truck Routing','spotter-weather-aware-routing','A full-stack route-planning application that compares routes using weather checkpoints, travel time, and load-sensitive risk rules.','Full Stack',array['Python','Django REST Framework','React','TypeScript','MapLibre','Open-Meteo','OSRM'],'https://github.com/MahdiNoorzadeh/spotter-ai-weather-aware-routing','https://spotter-ai-weather-aware-routing.vercel.app/','Route choice can change when weather conditions and driving time are considered together.','Built a map-based workflow to compare up to three routes and visualize forecast-based risk.','React and TypeScript frontend consuming a Django REST API, with OpenStreetMap, Open-Meteo, and OSRM integrations.','Combining routing and hourly forecast data into a clear, time-aware map experience.','Route comparison, risk visualization, and a 0–48 hour forecast view.','published',true,1),
('URL Shortener','url-shortener','A backend-focused URL shortener with redirects, expiration, click statistics, PostgreSQL persistence, and Redis Cache-Aside caching.','Backend',array['Java 25','Spring Boot','PostgreSQL','Redis','Flyway','Docker','JUnit','Mockito','Testcontainers'],'https://github.com/MahdiNoorzadeh/url-shortener',null,'Short links need predictable redirects, expiration behavior, and efficient repeated lookups.','Implemented URL creation, redirects, expiration, click statistics, and a Redis Cache-Aside pattern with URL-aligned TTL.','Spring Boot REST API backed by PostgreSQL, Redis caching, Flyway migrations, and Docker Compose.','Keeping cache TTL aligned with URL expiry and testing persistence and caching behavior.','OpenAPI documentation, health checks, validation, automated tests, and GitHub Actions CI.','published',true,2),
('CipherVault','ciphervault','A desktop API-token manager using AES-256-GCM encryption and operating-system keyring storage for the master key.','Desktop & Security',array['Electron','Vue 3','Vuetify','Realm','AES-256-GCM','Keytar'],'https://github.com/MahdiNoorzadeh/CipherVault',null,'Developer API tokens need safer local storage and clear separation between UI and privileged operations.','Built a desktop token manager with encrypted token records, project/environment organization, and OS-keyring master-key storage.','Electron main process handles privileged operations and cryptography while the Vue renderer uses validated IPC calls.','Reducing plaintext exposure and hardening the Electron renderer-to-main-process boundary.','Context isolation, restrictive renderer settings, Content Security Policy, IPC sender validation, and encryption tests.','published',true,3) on conflict(slug) do nothing;
